const $=s=>document.getElementById(s),video=$('video'),overlay=$('overlay'),oc=overlay.getContext('2d'),work=document.createElement('canvas'),wc=work.getContext('2d',{willReadFrequently:true});
let stream=null,running=false,demo=false,frozen=false,prev=null,tracks=[],nextId=1,last=0,stableUntil=0,torch=false,raf=0,micStream=null,ac=null,analyser=null,freq=null,audioRaf=0,audioHeld=0,token=0,micToken=0;
let motionEpoch=0;
const W=480;let H=360;
$('sens').oninput=()=>$('sensValue').textContent=$('sens').value;
function message(s){$('error').textContent=s}
function stop(){motionEpoch++;token++;running=false;demo=false;frozen=false;cancelAnimationFrame(raf);stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;prev=null;tracks=[];torch=false;$('start').textContent='카메라 시작';$('start').disabled=false;$('demo').textContent='움직임 테스트';$('freeze').disabled=true;$('freeze').textContent='화면 고정';$('torch').disabled=true;$('torch').textContent='조명 미지원';$('intro').hidden=false;$('zoom').hidden=true;$('count').textContent='후보 0';$('live').textContent='대기';$('visual').textContent='탐색 준비';$('guide').textContent='카메라를 켜면 탐색을 시작합니다';$('fps').textContent='0 FPS';oc.clearRect(0,0,overlay.width,overlay.height)}
function activate(isDemo){motionEpoch++;demo=isDemo;running=true;prev=null;tracks=[];stableUntil=performance.now()+700;last=0;$('intro').hidden=true;$('freeze').disabled=false;$('live').textContent=isDemo?'테스트 중':'탐색 중';$('mode').textContent=isDemo?'가상 움직임 · 실제 검출 아님':'카메라 · 영상은 기기 내 처리';$('start').textContent='탐지 중지';$('demo').textContent=isDemo?'테스트 종료':'움직임 테스트';raf=requestAnimationFrame(loop)}
$('start').onclick=async()=>{if(running){stop();return}if(!navigator.mediaDevices?.getUserMedia){message('카메라를 사용할 수 없습니다. HTTPS 주소를 Safari 또는 Chrome에서 열어 주세요.');return}const current=++token;$('start').disabled=true;message('');let acquired;try{acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080},frameRate:{ideal:30}},audio:false});if(current!==token){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;video.srcObject=stream;await video.play();if(current!==token)return;H=Math.round(W*video.videoHeight/video.videoWidth);const caps=stream.getVideoTracks()[0].getCapabilities?.()||{};$('torch').disabled=!caps.torch;$('torch').textContent=caps.torch?'조명 켜기':'조명 미지원';activate(false)}catch(e){acquired?.getTracks().forEach(t=>t.stop());stop();message(e.name==='NotAllowedError'?'카메라 권한이 차단되었습니다. 브라우저의 사이트 설정에서 허용한 뒤 다시 시작하세요.':'카메라를 열 수 없습니다. 다른 카메라 앱을 닫고 Safari 또는 Chrome에서 다시 시도하세요.')}finally{$('start').disabled=false}};
$('demo').onclick=()=>{const was=demo;stop();message('');if(!was){H=360;activate(true)}};
$('freeze').onclick=()=>{frozen=!frozen;$('freeze').textContent=frozen?'탐색 재개':'화면 고정';$('live').textContent=frozen?'화면 고정':demo?'테스트 중':'탐색 중';if(!demo){if(frozen)video.pause();else video.play().catch(()=>message('재생이 중단되었습니다. 카메라를 다시 시작하세요.'))}prev=null;tracks=[];if(!frozen)stableUntil=performance.now()+500};
$('torch').onclick=async()=>{try{const desired=!torch;await stream.getVideoTracks()[0].applyConstraints({advanced:[{torch:desired}]});torch=desired;$('torch').textContent=torch?'조명 끄기':'조명 켜기';prev=null}catch{message('이 카메라에서는 조명을 켤 수 없습니다.')}};
function detect(gray,t){if(!prev)return [];const mask=new Uint8Array(W*H);let changed=0;const threshold=58-Number($('sens').value)*.48;for(let i=0;i<gray.length;i++){if(Math.abs(gray[i]-prev[i])>threshold){mask[i]=1;changed++}}if(changed/(W*H)>.055){stableUntil=t+600;motionEpoch++;tracks=[];$('guide').textContent='화면 변화가 큽니다 · 잠시 멈춰 주세요';return []}if(t<stableUntil){$('guide').textContent='화면이 안정되면 탐색합니다';return []}$('guide').textContent=demo?'테스트 입력을 같은 탐지 알고리즘으로 분석 중':'천천히 훑고 잠시 멈추세요 · 표시된 후보를 눈으로 확인';const blobs=[];for(let p=0;p<mask.length;p++){if(!mask[p])continue;const q=[p];mask[p]=0;let sx=0,sy=0,n=0,minx=W,maxx=0,miny=H,maxy=0;for(let j=0;j<q.length;j++){const k=q[j],x=k%W,y=Math.floor(k/W);n++;sx+=x;sy+=y;minx=Math.min(minx,x);maxx=Math.max(maxx,x);miny=Math.min(miny,y);maxy=Math.max(maxy,y);for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,idx=ny*W+nx;if(nx>=0&&nx<W&&ny>=0&&ny<H&&mask[idx]){mask[idx]=0;q.push(idx)}}}if(n>=3&&n<=160&&maxx-minx<32&&maxy-miny<32)blobs.push({x:sx/n,y:sy/n,n})}return blobs.sort((a,b)=>b.n-a.n).slice(0,12)}
function associate(blobs,t){const used=new Set();for(const b of blobs){let best=null,dist=40;for(const tr of tracks){if(used.has(tr.id)||t-tr.time>300)continue;const d=Math.hypot(tr.x-b.x,tr.y-b.y);if(d<dist){dist=d;best=tr}}if(best){best.x=b.x;best.y=b.y;best.time=t;best.hits++;best.path.push([b.x,b.y]);best.path=best.path.slice(-20);used.add(best.id)}else{const tr={...b,id:nextId++,hits:1,time:t,path:[[b.x,b.y]]};tracks.push(tr);used.add(tr.id)}}tracks=tracks.filter(tr=>t-tr.time<250);return tracks.filter(tr=>tr.hits>=3&&t-tr.time<120).slice(0,5)}
function loop(t){if(!running)return;raf=requestAnimationFrame(loop);if(frozen||t-last<65)return;const elapsed=t-last;last=t;if(!demo&&video.readyState<2)return;if(work.width!==W||work.height!==H){work.width=W;work.height=H}if(demo){wc.fillStyle='#bbc8be';wc.fillRect(0,0,W,H);wc.fillStyle='#26332e';wc.beginPath();wc.arc(W*.5+Math.sin(t/800)*W*.27,H*.5+Math.cos(t/570)*H*.23,3,0,Math.PI*2);wc.fill()}else wc.drawImage(video,0,0,W,H);const d=wc.getImageData(0,0,W,H).data,gray=new Uint8Array(W*H);for(let p=0;p<gray.length;p++)gray[p]=d[p*4]*.3+d[p*4+1]*.59+d[p*4+2]*.11;const cs=associate(detect(gray,t),t);prev=gray;draw(cs);window.dispatchEvent(new CustomEvent('mosquito-motion',{detail:{epoch:motionEpoch,time:t,tracks:tracks.map(({id,x,y,hits,time})=>({id,x,y,hits,time}))}}));$('count').textContent='후보 '+cs.length;$('visual').textContent=cs.length?'작은 움직임 후보':t<stableUntil?'화면 안정화 중':'작은 움직임 탐색 중';$('fps').textContent=Math.min(15,Math.round(1000/elapsed))+' FPS'}
function draw(cs){const r=overlay.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H),ox=(r.width-W*scale)/2,oy=(r.height-H*scale)/2,dpr=devicePixelRatio||1;overlay.width=Math.round(r.width*dpr);overlay.height=Math.round(r.height*dpr);oc.setTransform(dpr,0,0,dpr,0,0);if(demo)oc.drawImage(work,ox,oy,W*scale,H*scale);oc.strokeStyle='#b5f45c';oc.fillStyle='#b5f45c';oc.lineWidth=2;oc.font='bold 13px sans-serif';for(const c of cs){oc.beginPath();c.path.forEach(([x,y],i)=>i?oc.lineTo(ox+x*scale,oy+y*scale):oc.moveTo(ox+x*scale,oy+y*scale));oc.stroke();const x=ox+c.x*scale,y=oy+c.y*scale;oc.strokeRect(x-18,y-18,36,36);oc.fillText('후보 '+c.id,Math.min(r.width-65,x+20),Math.max(20,y-20));if(c.path.length>3){const a=c.path[c.path.length-4],angle=Math.atan2(c.y-a[1],c.x-a[0]);oc.beginPath();oc.moveTo(x+Math.cos(angle)*28,y+Math.sin(angle)*28);oc.lineTo(x+Math.cos(angle+2.5)*9,y+Math.sin(angle+2.5)*9);oc.lineTo(x+Math.cos(angle-2.5)*9,y+Math.sin(angle-2.5)*9);oc.closePath();oc.fill()}}$('zoom').hidden=!cs.length;if(cs.length){const c=cs[0],zc=$('zoom').getContext('2d');zc.imageSmoothingEnabled=false;zc.drawImage(work,Math.max(0,Math.min(W-80,c.x-40)),Math.max(0,Math.min(H-60,c.y-30)),80,60,0,0,160,120)}}
function stopMic(){micToken++;cancelAnimationFrame(audioRaf);micStream?.getTracks().forEach(t=>t.stop());micStream=null;ac?.close().catch(()=>{});ac=null;analyser=null;audioHeld=0;$('mic').disabled=false;$('mic').textContent='마이크 켜기';$('micState').textContent='꺼짐';$('soundTitle').textContent='가까운 날갯짓 살펴보기';$('peak').textContent='— Hz';$('spectrum').getContext('2d').clearRect(0,0,600,100)}
$('mic').onclick=async()=>{if(micStream){stopMic();return}const current=++micToken;$('mic').disabled=true;message('');let acquired;try{ac=new(window.AudioContext||window.webkitAudioContext)();await ac.resume();acquired=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});if(current!==micToken){acquired.getTracks().forEach(t=>t.stop());return}micStream=acquired;analyser=ac.createAnalyser();analyser.fftSize=4096;analyser.smoothingTimeConstant=.65;ac.createMediaStreamSource(micStream).connect(analyser);freq=new Float32Array(analyser.frequencyBinCount);$('mic').textContent='마이크 끄기';$('micState').textContent='분석 중';audioLoop()}catch{acquired?.getTracks().forEach(t=>t.stop());stopMic();message('마이크를 열 수 없습니다. 마이크 권한을 허용하고 다시 시도하세요.')}finally{$('mic').disabled=false}};
function audioLoop(){if(!analyser)return;analyser.getFloatFrequencyData(freq);const step=ac.sampleRate/analyser.fftSize,lo=Math.ceil(200/step),hi=Math.floor(1000/step);let max=-120,peak=0,sum=0,n=0;for(let i=lo;i<=hi;i++){const v=Number.isFinite(freq[i])?freq[i]:-120;sum+=v;n++;if(v>max){max=v;peak=i*step}}const candidate=max>-65&&max-sum/n>13;audioHeld=candidate?Math.min(30,audioHeld+1):Math.max(0,audioHeld-2);$('peak').textContent=max>-90?Math.round(peak)+' Hz':'— Hz';$('soundTitle').textContent=audioHeld>15?'유사 대역 소리 · 모기 여부 미확인':'주변 소리 분석 중';const c=$('spectrum').getContext('2d');c.clearRect(0,0,600,100);for(let i=lo;i<=hi;i++){const h=Math.max(0,Math.min(100,(freq[i]+100)*1.5));c.fillStyle=audioHeld>15?'#b5f45c':'#628f87';c.fillRect((i-lo)/(hi-lo+1)*600,100-h,600/(hi-lo+1)-2,h)}audioRaf=requestAnimationFrame(audioLoop)}
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();stopMic()}});addEventListener('pagehide',()=>{stop();stopMic()});
